"""Compute league prizes per the group's rules. Usage: python3 -I compute.py <data_dir> <out_json>"""
import json, os, sys

data_dir, out = sys.argv[1], sys.argv[2]
FEE = 3000
SEASON_PCT = [18, 10, 7, 6, 5, 4]
WEEK_PCT, HALF_PCT, GWMAX_PCT, IMPROVE_PCT = 1, 3, 3, 3

L = lambda p: json.load(open(os.path.join(data_dir, p)))
boot, league = L("bootstrap.json"), L("league.json")
finished = [e["id"] for e in boot["events"] if e["finished"] and e["data_checked"]]
current_gw = max(finished)
members = [{"entry": r["entry"], "team": r["entry_name"], "manager": r["player_name"].strip()}
           for r in league["standings"]["results"]]
ids = [m["entry"] for m in members]
pot = FEE * len(members)
pct = lambda p: pot * p / 100

# net points per GW (gross points minus transfer hits)
net, total = {}, {}
for eid in ids:
    h = L(f"hist/{eid}.json")["current"]
    net[eid] = {r["event"]: r["points"] - r["event_transfers_cost"] for r in h}
    total[eid] = h[-1]["total_points"] if h else 0
    assert sum(net[eid].values()) == total[eid], eid

# A gameweek whose matches have started but that FPL has not closed yet (finished + data_checked).
# Its points already count in the totals, so the site shows it as provisional;
# its weekly prize waits until FPL closes it.
cur_ev = next((e for e in boot["events"] if e["is_current"]), None)
provisional_gw = None
if cur_ev and cur_ev["id"] > current_gw and any(net[e].get(cur_ev["id"], 0) for e in ids):
    provisional_gw = cur_ev["id"]
show_gw = provisional_gw or current_gw

def cached(path, cache):
    """Picks and live points of a finished GW never change, so they are fetched once and kept."""
    fn = os.path.join(data_dir, cache)
    if os.path.exists(fn):
        return json.load(open(fn))
    import time, urllib.request
    os.makedirs(os.path.dirname(fn), exist_ok=True)
    for attempt in range(4):
        try:
            req = urllib.request.Request("https://fantasy.premierleague.com/api" + path,
                                         headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=30) as r:
                d = json.loads(r.read())
            break
        except Exception:
            if attempt == 3:
                raise
            time.sleep(3 * (attempt + 1))
    json.dump(d, open(fn, "w"))
    return d

_live = {}
def live_points(gw):
    if gw not in _live:
        _live[gw] = {e["id"]: e["stats"]["total_points"]
                     for e in cached(f"/event/{gw}/live/", f"live/{gw}.json")["elements"]}
    return _live[gw]

def tiebreak(eid, gw):
    """Weekly tie-break order: all 15 players' points, captain, vice-captain, goalkeeper."""
    p = cached(f"/entry/{eid}/event/{gw}/picks/", f"picks/{eid}_{gw}.json")
    lp = live_points(gw)
    picks = p["picks"]
    all15 = sum(lp.get(x["element"], 0) for x in picks)
    cap = next(x["element"] for x in picks if x["is_captain"])
    vc = next(x["element"] for x in picks if x["is_vice_captain"])
    xi = [x["element"] for x in picks if x["position"] <= 11]
    for s in p.get("automatic_subs", []):
        if s["element_out"] in xi:
            xi[xi.index(s["element_out"])] = s["element_in"]
    gk = next(x["element"] for x in picks if x["element"] in xi and x["element_type"] == 1)
    return [all15, lp.get(cap, 0), lp.get(vc, 0), lp.get(gk, 0)]

won = {eid: 0.0 for eid in ids}
weeks = []
for gw in finished:
    scores = {eid: net[eid].get(gw, 0) for eid in ids}
    top = max(scores.values())
    tied = [eid for eid in ids if scores[eid] == top]
    tb = None
    if len(tied) > 1:
        tb = {eid: tiebreak(eid, gw) for eid in tied}
        best = max(tb.values())
        winners = [eid for eid in tied if tb[eid] == best]
    else:
        winners = tied
    for w in winners:
        won[w] += pct(WEEK_PCT) / len(winners)
    weeks.append({"gw": gw, "scores": scores, "top": top, "tied": tied,
                  "tiebreak": tb, "winners": winners})

def leaders(vals):
    best = max(vals.values())
    return [k for k, v in vals.items() if v == best], best

# season ranking: total, then H2H from latest GW backwards
order = sorted(ids, key=lambda e: [total[e]] + [net[e].get(g, 0) for g in sorted(finished, reverse=True)], reverse=True)
season = [{"entry": e, "rank": i + 1, "total": total[e],
           "projected": pct(SEASON_PCT[i]) if i < len(SEASON_PCT) else 0} for i, e in enumerate(order)]

h1 = {e: sum(v for g, v in net[e].items() if g <= 19) for e in ids}
h2 = {e: sum(v for g, v in net[e].items() if g >= 20) for e in ids}
gwmax = {e: max(net[e].values()) for e in ids}
h1_lead, h1_best = leaders(h1)
gm_lead, gm_best = leaders(gwmax)
gm_when = {e: [g for g, v in net[e].items() if v == gm_best] for e in gm_lead}

result = {
    "league": league["league"]["name"], "league_id": league["league"]["id"],
    "current_gw": current_gw, "next_gw": current_gw + 1, "fee": FEE, "pot": pot,
    "show_gw": show_gw, "provisional_gw": provisional_gw,
    "members": members, "net": {str(e): net[e] for e in ids}, "total": {str(e): total[e] for e in ids},
    "weeks": weeks, "weekly_won": {str(e): won[e] for e in ids},
    "season": season,
    "half1": {"scores": {str(e): h1[e] for e in ids}, "leaders": h1_lead, "best": h1_best, "prize": pct(HALF_PCT)},
    "half2": {"scores": {str(e): h2[e] for e in ids}, "prize": pct(HALF_PCT), "started": current_gw >= 20},
    "gwmax": {"scores": {str(e): gwmax[e] for e in ids}, "leaders": gm_lead, "best": gm_best,
              "when": {str(k): v for k, v in gm_when.items()}, "prize": pct(GWMAX_PCT)},
    "improve": {"prize": pct(IMPROVE_PCT), "started": current_gw >= 20},
    "pct_check": sum(SEASON_PCT) + 38 * WEEK_PCT + 2 * HALF_PCT + GWMAX_PCT + IMPROVE_PCT,
}
json.dump(result, open(out, "w"), ensure_ascii=False, indent=1)

name = {m["entry"]: m["manager"] for m in members}
print("pot", pot, "pct total", result["pct_check"], "GW", current_gw, "provisional GW", provisional_gw)
for w in weeks:
    print(f"GW{w['gw']:2d} top {w['top']:3d} tied {[name[t] for t in w['tied']]} tb {w['tiebreak']} -> {[name[x] for x in w['winners']]}")
print("half1 leaders", [name[x] for x in h1_lead], h1_best)
print("gwmax", [name[x] for x in gm_lead], gm_best, gm_when)
for s in season:
    print(s["rank"], name[s["entry"]], s["total"], s["projected"], "weekly won", won[s["entry"]])
